'use client';

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '../context/AuthContext';
import styles from '../page.module.css';
import Link from 'next/link';

interface Account {
  id: string;
  accountNumber: string;
  balance: number;
}

export default function Dashboard() {
  const { user, token, isAuthenticated, logout } = useAuth();
  const router = useRouter();
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!isAuthenticated) {
      router.push('/login');
      return;
    }

    fetch(`${process.env.NEXT_PUBLIC_API_URL}/api/accounts`, {
      headers: {
        'Authorization': `Bearer ${token}`
      }
    })
      .then(res => {
        if (res.status === 401 || res.status === 403) {
          logout();
          throw new Error('Unauthorized');
        }
        return res.json();
      })
      .then(data => {
        setAccounts(data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Failed to fetch accounts", err);
        setLoading(false);
      });
  }, [isAuthenticated, router, token, logout]);

  if (!isAuthenticated) return null;

  return (
    <div className={styles.container}>
      <header className={styles.header}>
        <div className={styles.logo}>Bank Modern</div>
        <nav className={styles.nav}>
          <Link href="/dashboard">Dashboard</Link>
          <Link href="/transfer">Transfer</Link>
          <Link href="/history">History</Link>
          <a href="#" onClick={(e) => { e.preventDefault(); logout(); }}>Logout</a>
        </nav>
      </header>

      <main className={styles.main}>
        <section className={styles.hero}>
          <h1>Welcome back, {user?.name || user?.email}</h1>
          <p>Here is an overview of your accounts.</p>
        </section>

        <section className={styles.dashboard}>
          {loading ? (
            <p>Loading accounts...</p>
          ) : accounts.length === 0 ? (
             <p>No accounts found.</p>
          ) : (
            accounts.map((account) => (
              <div key={account.id} className={styles.card}>
                <div className={styles.cardTitle}>{account.accountNumber}</div>
                <div className={styles.cardValue}>${account.balance.toFixed(2)}</div>
              </div>
            ))
          )}
        </section>
      </main>
    </div>
  );
}
